"""Generated by AetherLab - scenario: the pendulum race."""

import numpy as np
from manim import *


class AetherLabScene(Scene):
    def construct(self):
        # --- Scene 1: setup / brief ------------------------------------------
        title_top = Text(
            "Work, Energy & Newton's 2nd Law",
            font_size=38, weight=BOLD, color=YELLOW,
        ).to_edge(UP, buff=0.35)

        sub_top = Text(
            "m = 2 kg    v =    3 m/s",
            font_size=30, color=WHITE,
        ).next_to(title_top, DOWN, buff=0.25)

        # A small live-readout of the kinetic energy value.
        ke_value = ValueTracker(0.0)
        ke_live = always_redraw(lambda: DecimalNumber(
            ke_value.get_value(), num_decimal_places=1, font_size=44, color=YELLOW,
        ).move_to([0.0, 2.1, 0.0]))

        ke_label = Text("Kinetic Energy  KE", font_size=26, color=GREY_B).next_to(ke_live, UP, buff=0.18)
        ke_formula = MathTex("KE", "=", r"\tfrac{1}{2}", "m", "v^{2}",
                             font_size=46, color=WHITE).move_to([0.0, 0.85, 0.0])

        # Animate m and v ticking into the formula so the eye reads the substitution.
        m_box = SurroundingRectangle(ke_formula[3], color=BLUE, buff=0.08)
        v_box = SurroundingRectangle(ke_formula[4], color=ORANGE, buff=0.08)

        self.play(FadeIn(title_top, shift=0.2 * DOWN), FadeIn(sub_top),
                  FadeIn(ke_label), run_time=0.9)
        self.wait(0.3)
        self.play(Write(ke_formula), Create(m_box), Create(v_box),
                  FadeIn(ke_live), run_time=1.6)
        # Hop the value to the brief's actual answer: 1/2 * 2 * 3^2 = 9 J.
        ke_check = Text("= 9.0 J", font_size=32, color=YELLOW).next_to(ke_live, RIGHT, buff=0.25)
        self.play(
            ke_value.animate.set_value(9.0),
            FadeIn(ke_check),
            run_time=2.4, rate_func=smooth,
        )
        self.wait(0.8)

        # --- Scene 2: work-energy panel --------------------------------------
        setup = VGroup(title_top, sub_top, ke_label, ke_formula, m_box, v_box, ke_live, ke_check)
        for m in setup.get_family():
            m.clear_updaters()

        head2 = Text("From F = ma to Work and Energy",
                     font_size=34, weight=BOLD, color=YELLOW).to_edge(UP, buff=0.3)

        # The four governing relations, written as MathTex so they are crisp.
        eq_newton = MathTex("F", "=", "m", "a", font_size=44, color=WHITE)
        eq_accel = MathTex("a", "=", r"\dfrac{\Delta v}{\Delta t}",
                           font_size=40, color=WHITE)
        eq_work = MathTex("W", "=", "F", "d", font_size=44, color=BLUE)
        eq_ke = MathTex("W", "=", r"\Delta KE", "=", r"\tfrac{1}{2}", "m", "v_{f}^{2}",
                        "-", r"\tfrac{1}{2}", "m", "v_{i}^{2}",
                        font_size=38, color=TEAL)

        eqs = VGroup(eq_newton, eq_accel, eq_work, eq_ke).arrange(DOWN, buff=0.42)
        eqs.move_to([0.0, 1.2, 0.0])

        # A live work readout whose value is driven by DecimalNumber.set_value().
        work_value = ValueTracker(0.0)
        work_box = always_redraw(lambda: DecimalNumber(
            work_value.get_value(), num_decimal_places=1,
            font_size=40, color=BLUE,
        ).move_to([-4.0, -2.2, 0.0]))
        work_label = Text("Work done W", font_size=24, color=GREY_B).next_to(work_box, UP, buff=0.15)

        # Bracket that ties W = F*d on screen to the live readout.
        bracket = Brace(VGroup(eq_work[0], eq_work[4]), direction=DOWN, color=BLUE)
        bracket_label = Text("readout ↘", font_size=20, color=BLUE).next_to(bracket, DOWN, buff=0.12)

        self.play(TransformMatchingShapes(
            VGroup(setup), VGroup(head2),
            run_time=0.9,
        ))
        self.play(FadeIn(eq_newton, shift=0.2 * RIGHT),
                  Indicate(eq_newton[2], color=BLUE, scale_factor=1.25), run_time=0.7)
        self.play(FadeIn(eq_accel), FadeIn(eq_work), FadeIn(eq_ke), run_time=1.0)
        self.wait(0.3)

        self.play(FadeIn(work_label), FadeIn(work_box),
                  Create(bracket), FadeIn(bracket_label), run_time=0.8)

        # Live-driven count-up of the work value, then a single Indicate on W=Fd.
        self.play(work_value.animate.set_value(12.0),
                  Indicate(eq_work, color=BLUE, scale_factor=1.1),
                  run_time=2.0, rate_func=smooth)
        self.wait(0.6)

        # --- Scene 3: kinematics demo on a number line -----------------------
        explain = VGroup(head2, eqs, work_label, work_box, bracket, bracket_label)
        for m in explain.get_family():
            m.clear_updaters()

        head3 = Text("Same numbers, in motion", font_size=34, weight=BOLD,
                     color=YELLOW).to_edge(UP, buff=0.3)

        # Number line with ticks.
        line = NumberLine(
            x_range=[-1, 9, 1], length=10.0, color=GREY_B,
            include_numbers=True, label_direction=DOWN, font_size=22,
        ).move_to([0.0, -0.6, 0.0])

        # A tracked dot whose x-position is set_value() driven.
        pos = ValueTracker(0.0)
        dot = always_redraw(lambda: Dot(
            [pos.get_value() - 0.5, -0.6, 0.0], radius=0.13, color=BLUE,
        ))

        # The velocity is constant v = 3 m/s; we visualize the displacement arrow
        # that grows as the dot travels.
        arrow = always_redraw(lambda: Arrow(
            start=[-0.5, -0.6, 0.0],
            end=[pos.get_value() - 0.5, -0.6, 0.0],
            buff=0.0, color=BLUE, stroke_width=6,
        ))

        v_label = Text("v = 3 m/s (constant)",
                       font_size=26, color=BLUE).move_to([0.0, 2.2, 0.0])
        d_value = ValueTracker(0.0)
        d_live = always_redraw(lambda: DecimalNumber(
            d_value.get_value(), num_decimal_places=1,
            font_size=36, color=YELLOW,
        ).move_to([0.0, 1.45, 0.0]))
        d_label = Text("displacement d (m)", font_size=22,
                       color=GREY_B).next_to(d_live, UP, buff=0.12)

        # Force/acceleration readout. a = F/m, here F=6 N, m=2 kg → a = 3 m/s².
        a_label = Text("a = F/m = 6/2 = 3 m/s²",
                       font_size=26, color=ORANGE).move_to([0.0, -2.3, 0.0])
        # Live W = F·d readout.
        w_live = always_redraw(lambda: DecimalNumber(
            6.0 * d_value.get_value(), num_decimal_places=1,
            font_size=36, color=TEAL,
        ).move_to([5.4, 1.45, 0.0]))
        w_label = Text("W = F·d (J)", font_size=22,
                       color=GREY_B).next_to(w_live, UP, buff=0.12)

        # Clean previous content and bring in scene 3 elements in one play.
        self.play(
            *[FadeOut(m) for m in self.mobjects],
            FadeIn(head3),
            run_time=0.7,
        )
        self.play(Create(line), FadeIn(v_label),
                  FadeIn(a_label),
                  run_time=1.0)
        self.add(dot, arrow, d_live, d_label, w_live, w_label)
        # Move the dot while dragging the displacement number and the live W readout.
        self.play(
            pos.animate.set_value(8.0),
            d_value.animate.set_value(8.0),
            run_time=4.0, rate_func=linear,
        )
        self.wait(0.4)

        # --- Scene 4: climax / comparison ------------------------------------
        live = VGroup(head3, line, dot, arrow, v_label, d_live, d_label,
                      w_live, w_label, a_label)
        for m in live.get_family():
            m.clear_updaters()

        head4 = Text("Compare the two work readouts",
                     font_size=34, weight=BOLD, color=YELLOW).to_edge(UP, buff=0.3)

        # Two side-by-side cards with the same equations, different accents.
        card_l = RoundedRectangle(width=5.2, height=2.4, corner_radius=0.18,
                                  color=BLUE, stroke_width=4).move_to([-3.1, 0.4, 0])
        card_r = RoundedRectangle(width=5.2, height=2.4, corner_radius=0.18,
                                  color=ORANGE, stroke_width=4).move_to([3.1, 0.4, 0])

        eq_left = MathTex("W", "=", "F", "d", "=", "(6)", "(8)", "=", "48", r"\ \text{J}",
                          font_size=34, color=WHITE).move_to(card_l.get_center())
        eq_right = MathTex("KE", "=", r"\tfrac{1}{2}", "m", "v^{2}", "=", r"\tfrac{1}{2}", "(2)", "(9)", "=", "9", r"\ \text{J}",
                           font_size=34, color=WHITE).move_to(card_r.get_center())
        eq_left[7].set_color(YELLOW)
        eq_right[10].set_color(YELLOW)

        sub_l = Text("Work done by F = 6 N over 8 m",
                     font_size=22, color=BLUE).next_to(card_l, DOWN, buff=0.22)
        sub_r = Text("Kinetic energy at v = 3 m/s, m = 2 kg",
                     font_size=22, color=ORANGE).next_to(card_r, DOWN, buff=0.22)

        # The brief's hero equation, placed in the climax frame.
        hero = MathTex("W", "=", r"\Delta KE",
                       font_size=58, color=YELLOW).move_to([0.0, -2.3, 0.0])
        hero_box = SurroundingRectangle(hero, color=YELLOW, buff=0.22,
                                        corner_radius=0.12)

        self.play(FadeIn(head4),
                  *[FadeOut(m) for m in self.mobjects if m is not head4],
                  Create(card_l), Create(card_r),
                  run_time=0.9)
        self.play(Write(eq_left), Write(eq_right),
                  FadeIn(sub_l), FadeIn(sub_r),
                  FadeIn(hero), Create(hero_box), run_time=1.8)
        self.play(Indicate(hero, color=YELLOW, scale_factor=1.12),
                  Indicate(hero_box, color=YELLOW), run_time=0.8)

        # Living ending: the live work number keeps ticking while KE stays put,
        # so the last sampled frames differ frame-to-frame.
        tail_w = ValueTracker(48.0)
        tail_live = always_redraw(lambda: DecimalNumber(
            tail_w.get_value(), num_decimal_places=1, font_size=34, color=BLUE,
        ).move_to([eq_left.get_center()[0], eq_left.get_center()[1] - 0.85, 0]))
        tail_label = Text("W (live)", font_size=20, color=GREY_B).next_to(
            tail_live, UP, buff=0.08)
        self.add(tail_live, tail_label)
        self.play(tail_w.animate.set_value(60.0), run_time=3.0, rate_func=smooth)
        self.wait(0.6)